"use server";
import { z } from "zod";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { createReportToken, REPORT_TYPES, type ReportFilters } from "@/lib/reports/security";
import { redirect } from "next/navigation";

const authSchema = z.object({ email: z.string().email(), password: z.string().min(8) });
export async function signIn(formData: FormData) {
  const parsed = authSchema.safeParse({ email: formData.get("email"), password: formData.get("password") });
  if (!parsed.success) redirect("/login?error=Check+your+email+and+password");
  const supabase = await createClient();
  if (!supabase) redirect("/login?error=Add+Supabase+environment+variables+to+continue");
  const { error } = await supabase.auth.signInWithPassword(parsed.data);
  if (error) redirect("/login?error=Unable+to+sign+in.+Check+your+credentials.");
  const { data: { user } } = await supabase.auth.getUser();
  const { data: profile } = await supabase.from("profiles").select("role,account_status").eq("id", user!.id).maybeSingle();
  if(profile?.account_status!=="active")redirect("/account/status");
  redirect(profile?.role ? `/${profile.role}` : "/student");
}

const signupSchema = z.object({ name: z.string().min(2).max(100), email: z.string().email(), password: z.string().min(8), role: z.enum(["student","tutor","customer"]), qualifications:z.string().max(2000) });
export async function signUp(formData: FormData) {
  const parsed = signupSchema.safeParse({ name: formData.get("name"), email: formData.get("email"), password: formData.get("password"), role: formData.get("role"), qualifications:formData.get("qualifications")||"" });
  if (!parsed.success) redirect("/signup?error=Please+complete+all+fields.+Password+must+be+8+characters.");
  const supabase = await createClient();
  if (!supabase) redirect("/signup?error=Add+Supabase+environment+variables+to+continue");
  const { data, error } = await supabase.auth.signUp({ email: parsed.data.email, password: parsed.data.password, options: { data: { full_name: parsed.data.name, role: parsed.data.role, qualification_summary:parsed.data.qualifications } } });
  if (error || !data.user) redirect("/signup?error=Unable+to+create+account.+Try+another+email.");
  redirect("/login?message=Account+created.+Check+your+email+to+verify+your+account.");
}

const enrolmentSchema=z.string().uuid();
export async function enrolInCourse(formData:FormData){
  const courseId=enrolmentSchema.safeParse(formData.get("courseId"));
  if(!courseId.success)redirect("/courses?error=Choose+a+valid+course");
  const supabase=await createClient();if(!supabase)redirect("/login?error=Connect+Supabase+before+enrolling");
  const {data:{user}}=await supabase.auth.getUser();if(!user)redirect("/login?message=Log+in+as+a+student+to+enrol");
  const {data:profile}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();
  if(profile?.role!=="student")redirect("/courses?error=Only+student+accounts+can+enrol");
  const {error}=await supabase.from("enrolments").insert({student_id:user.id,course_id:courseId.data,status:"pending"});
  if(error?.code==="23505")redirect("/student/courses?message=You+are+already+enrolled+in+that+course");
  if(error)redirect("/courses?error=Unable+to+complete+enrolment");
  redirect("/student/courses?message=You+are+enrolled");
}

const bookingSchema=z.object({professionalId:z.string().uuid(),serviceId:z.string().uuid(),scheduledAt:z.string().min(16).max(20),notes:z.string().max(1000),deliveryMethod:z.enum(["business","home_service","online"]),serviceLocation:z.string().max(500)});
export async function requestBooking(formData:FormData){
  const parsed=bookingSchema.safeParse({professionalId:formData.get("professionalId"),serviceId:formData.get("serviceId"),scheduledAt:formData.get("scheduledAt"),notes:formData.get("notes")||"",deliveryMethod:formData.get("deliveryMethod")||"business",serviceLocation:formData.get("serviceLocation")||""});
  if(!parsed.success)redirect("/marketplace?error=Please+choose+a+valid+appointment+time");
  const date=new Date(`${parsed.data.scheduledAt}:00+03:00`);if(Number.isNaN(date.getTime())||date.getTime()<Date.now()+60*60*1000)redirect(`/professionals/${parsed.data.professionalId}?error=Choose+a+time+at+least+one+hour+from+now`);
  const supabase=await createClient();if(!supabase)redirect("/login?error=Connect+Supabase+before+booking");
  const {data:{user}}=await supabase.auth.getUser();if(!user)redirect("/login?message=Log+in+as+a+customer+to+request+a+booking");
  const {data:profile}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();if(profile?.role!=="customer")redirect("/professionals/"+parsed.data.professionalId+"?error=Please+sign+in+with+a+customer+account");
  const {error}=await supabase.functions.invoke("marketplace-transactions",{body:{operation:"request_booking",professional_id:parsed.data.professionalId,service_id:parsed.data.serviceId,scheduled_at:date.toISOString(),notes:parsed.data.notes,delivery_method:parsed.data.deliveryMethod,service_location:parsed.data.serviceLocation||null}});
  if(error)redirect(`/professionals/${parsed.data.professionalId}?error=${encodeURIComponent(error.message).replaceAll("%20","+")}`);
  redirect("/customer/bookings?message=Your+booking+request+was+sent");
}

