export async function uploadProfessionalPortfolio(formData:FormData){const caption=z.string().max(240).safeParse(formData.get("caption")||"");const consent=formData.get("consent")==="yes",file=formData.get("image");if(!caption.success||!consent||!(file instanceof File)||file.size<1||file.size>10*1024*1024)redirect("/professional/profile?error=Choose+a+portfolio+image+under+10MB+and+confirm+you+have+permission");const bytes=new Uint8Array(await file.arrayBuffer());let mime="",ext="";if(bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff){mime="image/jpeg";ext="jpg";}else if(bytes[0]===0x89&&new TextDecoder().decode(bytes.slice(1,4))==="PNG"){mime="image/png";ext="png";}else if(new TextDecoder().decode(bytes.slice(0,4))==="RIFF"&&new TextDecoder().decode(bytes.slice(8,12))==="WEBP"){mime="image/webp";ext="webp";}else redirect("/professional/profile?error=Only+valid+JPEG,+PNG+or+WebP+images+are+accepted");const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {data:pro}=await db.from("professionals").select("id").eq("profile_id",user.id).maybeSingle();if(!pro)redirect("/professional/profile?error=Create+a+professional+profile+first");const path=`${user.id}/${pro.id}/${crypto.randomUUID()}.${ext}`;const uploaded=await db.storage.from("professional-portfolios").upload(path,bytes,{contentType:mime,upsert:false});if(uploaded.error)redirect(`/professional/profile?error=${encodeURIComponent(uploaded.error.message).replaceAll("%20","+")}`);const saved=await db.from("professional_portfolio").insert({professional_id:pro.id,image_path:path,caption:caption.data,consent_confirmed:true});if(saved.error){await db.storage.from("professional-portfolios").remove([path]);redirect(`/professional/profile?error=${encodeURIComponent(saved.error.message).replaceAll("%20","+")}`);}redirect("/professional/profile?message=Portfolio+image+submitted+for+approval");}
