const moderationSchema=z.object({id:z.string().uuid(),entity:z.enum(["tutor","course","professional","feedback","service"])});
export async function approveRecord(formData:FormData){
  const parsed=moderationSchema.safeParse({id:formData.get("id"),entity:formData.get("entity")});
  if(!parsed.success)redirect("/admin?error=Invalid+approval+request");
  const supabase=await createClient();if(!supabase)redirect("/login");
  const {data:{user}}=await supabase.auth.getUser();if(!user)redirect("/login");
  const {data:profile}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();if(profile?.role!=="admin")redirect("/student");
  const {id,entity}=parsed.data;
  const result=entity==="tutor"
    ?await supabase.functions.invoke("manage-user-access",{body:{targetUserId:id,kind:"tutor_decision",decision:"approved"}})
    :entity==="course"
      ?await supabase.functions.invoke("admin-governance",{body:{operation:"approve_course",id}})
      :entity==="professional"
        ?await supabase.functions.invoke("admin-governance",{body:{operation:"review_professional",id,decision:"published",notes:"Approved by administrator"}})
        :entity==="service"
          ?await supabase.functions.invoke("admin-governance",{body:{operation:"review_service",id,decision:"published"}})
          :await supabase.from("feedback").update({status:"approved"}).eq("id",id).eq("status","pending");
  if(result.error)redirect(`/admin?error=Unable+to+approve+this+record`);
  const page=entity==="tutor"?"people?role=tutor":entity==="course"?"courses":entity==="professional"||entity==="service"?"marketplace":"feedback";
  redirect(`/admin/${page}${entity==="tutor"?"&":"?"}message=Record+approved`);
}
