const reportRequestSchema=z.object({reportType:z.enum(REPORT_TYPES),format:z.enum(["csv","pdf"]),startDate:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().or(z.literal("")),endDate:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().or(z.literal("")),programmeId:z.string().uuid().optional().or(z.literal("")),courseId:z.string().uuid().optional().or(z.literal("")),moduleId:z.string().uuid().optional().or(z.literal("")),tutorId:z.string().uuid().optional().or(z.literal("")),studentId:z.string().uuid().optional().or(z.literal("")),status:z.enum(reportStatusValues).optional().or(z.literal(""))}).refine(v=>!v.startDate||!v.endDate||v.endDate>=v.startDate,{path:["endDate"],message:"End date must be after start date"}).refine(v=>v.reportType!=="student_progress"||Boolean(v.studentId),{path:["studentId"],message:"Choose a student for an individual progress report"});
