export async function reviewAccountAction(formData:FormData){const id=z.string().uuid().safeParse(formData.get("requestId")),decision=z.enum(["approved","rejected"]).safeParse(formData.get("decision"));if(!id.success||!decision.success)redirect("/admin/account-requests?error=Invalid+review");const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {error}=await db.functions.invoke("admin-users",{body:{operation:"review_request",request_id:id.data,decision:decision.data}});if(error)redirect("/admin/account-requests?error=Unable+to+review+request");redirect("/admin/account-requests?message=Request+reviewed");}

export async function reviewMarketplaceBooking(formData:FormData){const id=z.string().uuid().safeParse(formData.get("bookingId")),status=z.enum(["confirmed","rescheduling_requested","cancelled","completed","no_show","disputed"]).safeParse(formData.get("status")),notes=z.string().max(2000).safeParse(formData.get("notes")||"");if(!id.success||!status.success||!notes.success)redirect("/admin/bookings?error=Check+the+booking+update");const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {error}=await db.functions.invoke("admin-governance",{body:{operation:"review_booking",id:id.data,status:status.data,notes:notes.data}});if(error)redirect("/admin/bookings?error=Unable+to+update+booking");redirect("/admin/bookings?message=Booking+updated");}
export async function adminResetProfile(formData:FormData){const id=z.string().uuid().safeParse(formData.get("userId")),returnTo=z.enum(["/admin/people","/admin/users"]).safeParse(formData.get("returnTo")||"/admin/people"),dest=returnTo.success?returnTo.data:"/admin/people";if(!id.success)redirect(`${dest}?error=Invalid+account`);const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {error}=await db.functions.invoke("admin-users",{body:{operation:"reset_profile",user_id:id.data}});if(error)redirect(`${dest}?error=Unable+to+reset+profile`);redirect(`${dest}?message=Profile+fields+reset`);}
export async function adminDeleteUser(formData:FormData){const id=z.string().uuid().safeParse(formData.get("userId")),email=z.string().email().safeParse(formData.get("confirmEmail")),returnTo=z.enum(["/admin/people","/admin/users"]).safeParse(formData.get("returnTo")||"/admin/people"),dest=returnTo.success?returnTo.data:"/admin/people";if(!id.success||!email.success)redirect(`${dest}?error=Enter+the+account+email+to+confirm+deletion`);const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {error}=await db.functions.invoke("admin-users",{body:{operation:"delete_user",user_id:id.data,confirm_email:email.data}});if(error)redirect(`${dest}?error=Unable+to+delete+this+account`);redirect(`${dest}?message=Account+deleted`);}
export async function adminSetUserStatus(formData:FormData){const id=z.string().uuid().safeParse(formData.get("userId")),status=z.enum(["active","suspended","deactivated"]).safeParse(formData.get("status"));if(!id.success||!status.success)redirect("/admin/users?error=Choose+a+valid+account+status");const db=await createClient();if(!db)redirect("/login");const {data:{user}}=await db.auth.getUser();if(!user)redirect("/login");const {error}=await db.functions.invoke("admin-users",{body:{operation:"set_status",user_id:id.data,status:status.data}});if(error)redirect("/admin/users?error=Unable+to+update+user+status");redirect("/admin/users?message=User+status+updated");}
